package africa.growtogether.platform.ewe.task; import static africa.growtogether.platform.ewe.task.TaskDtos.*; import africa.growtogether.platform.common.api.*; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/workflow-tasks") public class WorkflowTaskController {private final WorkflowTaskService service;private final ApiResponses responses;public WorkflowTaskController(WorkflowTaskService s,ApiResponses r){service=s;responses=r;} @PostMapping @PreAuthorize("hasAuthority('workflow.tasks.create')") public ApiResponse<TaskView> create(@RequestBody CreateTask c){return responses.success(service.create(c));} @GetMapping("/instance/{id}") @PreAuthorize("hasAuthority('workflow.tasks.read')") public ApiResponse<?> byInstance(@PathVariable UUID id){return responses.success(service.byInstance(id));} @PostMapping("/{id}/claim/{userId}") @PreAuthorize("hasAuthority('workflow.tasks.claim')") public ApiResponse<TaskView> claim(@PathVariable UUID id,@PathVariable UUID userId){return responses.success(service.claim(id,userId));} @PostMapping("/{id}/start") @PreAuthorize("hasAuthority('workflow.tasks.execute')") public ApiResponse<TaskView> start(@PathVariable UUID id){return responses.success(service.start(id));} @PostMapping("/{id}/complete") @PreAuthorize("hasAuthority('workflow.tasks.execute')") public ApiResponse<TaskView> complete(@PathVariable UUID id,@RequestBody CompleteTask c){return responses.success(service.complete(id,c));} @PostMapping("/{id}/decision") @PreAuthorize("hasAuthority('workflow.tasks.approve')") public ApiResponse<TaskView> decide(@PathVariable UUID id,@RequestBody Decision c){return responses.success(service.decide(id,c));} @PostMapping("/{id}/delegate") @PreAuthorize("hasAuthority('workflow.tasks.delegate')") public ApiResponse<TaskView> delegate(@PathVariable UUID id,@RequestBody Delegate c){return responses.success(service.delegate(id,c));} @PostMapping("/{id}/escalate") @PreAuthorize("hasAuthority('workflow.tasks.escalate')") public ApiResponse<TaskView> escalate(@PathVariable UUID id,@RequestParam(required=false) UUID to){return responses.success(service.escalate(id,to));} @PostMapping("/routing-rules") @PreAuthorize("hasAuthority('workflow.routing.manage')") public ApiResponse<UUID> rule(@RequestBody CreateRoutingRule c){return responses.success(service.createRule(c));}}
